import { items_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "CategoryDialog",
  props: {
    dialog: Boolean,
    editingCategory: Object
  },
  data() {
    return {
      loading: false,
      categoryForm: {
        category_name: ""
      }
    };
  },
  watch: {
    editingCategory: {
      immediate: true,
      handler(val) {
        this.categoryForm = val ? {
          ...val
        } : {
          category_name: ""
        };
      }
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked");
      this.$refs.form?.reset();
      this.$refs.form?.resetValidation();
    },
    async save_category() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (!valid) return;
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(items_categories, {
          input: {
            category_id: this.editingCategory?.category_id,
            category_name: this.categoryForm.category_name,
            action_type: this.editingCategory ? "UPDATE" : "CREATE"
          }
        }));
        const res = JSON.parse(result.data.items_categories);
        res.Status === "SUCCESS" ? this.$emit("successMsg", res.Message) : this.$emit("errorMsg", res.Message);
      } catch (e) {
        this.$emit("errorMsg", e.message);
      } finally {
        this.loading = false;
      }
    }
  }
};
